// rustc --edition=2021 -O -C target-cpu=native; input from matching_pack.py.
#[allow(dead_code)]mod bitsrc{
include!("ramsey310_bulk_side.rs");
struct M {g:Vec<u32>, s:Vec<u32>, inc:[B;26], trip:Vec<B>, six:Vec<u32>, five:Vec<u32>, miss6:Vec<B>,miss5:Vec<B>,single:Vec<Vec<B>>, paired:Vec<B>, full:B}
impl M{
fn new(g:Vec<u32>,five:Vec<u32>,six:Vec<u32>,s:Vec<u32>)->Self{let n=s.len();assert!(n<=768);let mask=|t:u32|{let mut m=B::default();for(i,&v)in s.iter().enumerate(){if t&v==0{m.put(i)}}m};let miss:Vec<_>=s.iter().copied().map(mask).collect();let miss6=six.iter().copied().map(mask).collect();let miss5=five.iter().copied().map(mask).collect();let mut trip=vec![B::default();n*n];let mut init=vec![B::default();n];let mut paired=vec![B::default();n];let mut inc=[B::default();26];let mut full=B::default();for(i,&v)in s.iter().enumerate(){full.put(i);for h in 0..26{if v>>h&1!=0{inc[h].put(i)}}for j in 0..i{let common=miss[i].and(miss[j]);let mut z=B::default();common.each(|q|z.add(miss[q]));trip[i*n+j]=z;trip[j*n+i]=z;if (v&s[j]).count_ones()<=4{init[i].put(j);init[j].put(i)}if common.count()==0&&(v&s[j]).count_ones()<=5{paired[i].put(j);paired[j].put(i)}}}let mut single=Vec::new();for m in &miss{let mut a=init.clone();m.each(|t|filter(&mut a,miss[t]));single.push(a)}Self{g,s,inc,trip,six,five,miss6,miss5,single,paired,full}}
fn dfs(&self,adj:&[B],mut pool:B,k:usize,lo:[i8;26],hi:[i8;26],ids:&mut[usize;6])->bool{if k==0{return lo.iter().all(|&v|v<=0)}for v in 0..26{if lo[v]>k as i8||hi[v]<0{return false}if hi[v]==0{pool.sub(self.inc[v])}if lo[v]==k as i8{pool=pool.and(self.inc[v])}}let mut opt=pool;let mut size=opt.count();if size<k as u32{return false}for v in 0..26{if lo[v]>0{let b=pool.and(self.inc[v]);let c=b.count();if c<lo[v]as u32{return false}if c<size{opt=b;size=c}}}for w in 0..12{let mut x=opt.0[w];while x!=0{let b=x.trailing_zeros() as usize;x&=x-1;pool.0[w]&=!(1<<b);let i=64*w+b;let mut p=pool.and(adj[i]);for &j in &ids[..6-k]{p.sub(self.trip[i*self.s.len()+j])}if p.count()+1<k as u32{continue}let mut t=self.s[i];let(mut l,mut h)=(lo,hi);while t!=0{let v=t.trailing_zeros()as usize;t&=t-1;l[v]-=1;h[v]-=1}ids[6-k]=i;if self.dfs(adj,p,k-1,l,h,ids){return true}}}false}
fn run(&self){let mut total=0;let mut passed=0;for i in 0..self.s.len(){self.paired[i].each(|j|{if j>=i{return}let mut pair_adj:Vec<_>=self.single[i].iter().zip(&self.single[j]).map(|(&a,&b)|a.and(b)).collect();let u=self.s[i]|self.s[j];for(t,&v)in self.six.iter().enumerate(){if v&u==0{filter(&mut pair_adj,self.miss6[t])}}self.paired[i].and(self.paired[j]).each(|k|{if k>=j{return}let z=self.s[k];let union=u|z;if self.six.iter().any(|&s|s&union==0){return}total+=1;let mut a:Vec<_>=pair_adj.iter().zip(&self.single[k]).map(|(&a,&b)|a.and(b)).collect();for(t,&v)in self.six.iter().enumerate(){if v&z==0&&(v&self.s[i]==0||v&self.s[j]==0){filter(&mut a,self.miss6[t])}}for(t,&v)in self.five.iter().enumerate(){if v&union==0{filter(&mut a,self.miss5[t])}}let mut hi=[0i8;26];let mut lo=hi;for v in 0..26{let deg=self.g[v].count_ones()as i8;lo[v]=(6-deg).max(1);hi[v]=9-deg-((self.s[i]>>v&1)+(self.s[j]>>v&1)+(z>>v&1))as i8;if hi[v]==1{filter(&mut a,self.inc[v])}}if self.dfs(&a,self.full,6,lo,hi,&mut[0;6]){passed+=1;println!("{} {} {}",self.s[i],self.s[j],z)}})})}eprintln!("admissible sides {total}, passed {passed}")}}
pub fn start(){let txt=fs::read_to_string(env::args().nth(1).unwrap()).unwrap();let mut it=txt.split_whitespace().map(|x|x.parse::<u32>().unwrap());let mut read=||{let n=it.next().unwrap();(0..n).map(|_|it.next().unwrap()).collect::<Vec<_>>()};M::new(read(),read(),read(),read()).run()}}
fn main(){bitsrc::start()}
